import Foundation

/// 40 Atlas-taxonomy techniques. Verbatim port of web src/lib/techniques.ts (+ contrast).
/// Each entry now carries the full Atlas record: id, name, cluster, mechanism,
/// verdict, folklore risk, canonical source, primary failure mode,
/// contraindication. Lessons detail view renders all of these.
public enum AtlasTechniques {
    public static let all: [Technique] = [
        // A · Compliance-gaining
        Technique(id: "fitd",     name: "Foot-in-the-door",     cluster: .compliance, mechanism: "Small initial compliance creates self-perception of being a compliant person; subsequent larger request is harder to refuse without identity inconsistency.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Cialdini 1984; Freedman & Fraser 1966", primaryFailureMode: "Reverse-causation: in commercial repeat-game contexts, the small ask can poison the target if perceived as transactional.", contraindication: "Single-shot consumer contexts where the target sees you only once; identity-relevance must hold."),
        Technique(id: "ditf",     name: "Door-in-the-face",     cluster: .compliance, mechanism: "Large initial request creates perception of concession when retreating to target; reciprocity norm activated.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984; O'Keefe & Hale 1998", primaryFailureMode: "Initial request implausible enough to insult; technique reads as manipulation.", contraindication: "Procurement specialists or persuasion-knowledge-high buyers."),
        Technique(id: "lowball",  name: "Low-ball",             cluster: .compliance, mechanism: "Initial small commitment binds participant; raised price after commitment is harder to refuse than same price offered initially.", atlasVerdict: .partiallyStudied, folkloreRisk: .mediumHigh, canonicalSource: "Cialdini et al. 1978", primaryFailureMode: "Catastrophic in repeat-game; experienced as deception at renewal.", contraindication: "Any repeat-game commercial context. Ethics-flagged."),
        Technique(id: "tna",      name: "That's-not-all",       cluster: .compliance, mechanism: "Sequential added bonuses before counter-offer activates reciprocity and value-anchoring.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Burger 1986", primaryFailureMode: "Density past buyer's perceived-fairness threshold reads as desperation.", contraindication: "Procurement; persuasion-knowledge-high buyers."),
        Technique(id: "disrupt-then-reframe", name: "Disrupt-then-reframe", cluster: .compliance, mechanism: "Unexpected pattern disruption creates micro-confusion; reframe in same breath bypasses critical evaluation.", atlasVerdict: .replicationFailed, folkloreRisk: .high, canonicalSource: "Davis & Knowles 1999 (replication concerns: Carpenter 2013)", primaryFailureMode: "Original cupcake-study replication failed. Brittle technique.", contraindication: "Any context where the reframe doesn't survive the buyer's later reflection."),

        // B · Cialdini six principles
        Technique(id: "reciprocity",   name: "Reciprocity",                 cluster: .cialdini, mechanism: "Norm of reciprocation creates obligation following unsolicited gift, favor, or concession.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Cialdini 1984; Regan 1971", primaryFailureMode: "Over-leveraged reciprocity degrades into transactional perception.", contraindication: "Frequent gifts to same buyer; transparent transactional framing."),
        Technique(id: "scarcity",      name: "Scarcity",                    cluster: .cialdini, mechanism: "Loss-aversion plus reactance: limited availability raises perceived value and urgency.", atlasVerdict: .wellStudied, folkloreRisk: .lowMedium, canonicalSource: "Cialdini 1984", primaryFailureMode: "Manufactured scarcity detected = trust collapse plus reactance.", contraindication: "Any context where scarcity claim is unverifiable or falsifiable."),
        Technique(id: "authority",     name: "Authority cues",              cluster: .cialdini, mechanism: "Heuristic deference to expertise or status reduces deliberation cost.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984; Milgram", primaryFailureMode: "Titular authority without specific expertise triggers persuasion-knowledge.", contraindication: "Specificity-of-credential is the discriminator; never claim titular."),
        Technique(id: "social-proof",  name: "Social proof",                cluster: .cialdini, mechanism: "Uncertainty resolved by observing others' behavior; conformity heuristic activates.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Cialdini 1984; Deutsch & Gerard 1955", primaryFailureMode: "Generic social-proof ('thousands of customers') has low specificity-effect.", contraindication: "When peer set is dissimilar to buyer; named peers in same industry, role, stage carry weight."),
        Technique(id: "liking",        name: "Liking / similarity / rapport", cluster: .cialdini, mechanism: "Affect transfer from liked source to evaluated offer; similarity activates in-group cooperative heuristics.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984", primaryFailureMode: "Confusing warmth-of-interaction with accuracy-of-other-model.", contraindication: "Never substitute liking for understanding."),
        Technique(id: "commitment-consistency", name: "Commitment & consistency", cluster: .cialdini, mechanism: "Prior public stance creates pressure to act consistently.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984; SPIN (Rackham 1988)", primaryFailureMode: "Public plus written plus effortful commitments compound the effect; lone verbal weak.", contraindication: "When buyer feels trapped rather than guided."),

        // C · Framing
        Technique(id: "loss-framing",    name: "Loss-aversion framing",       cluster: .framing, mechanism: "Asymmetric weighting of losses vs gains; status-quo bias activated.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Tversky & Kahneman 1981; Challenger Sale 2011", primaryFailureMode: "Over-deployed fear-frame triggers reactance.", contraindication: "Promotion-focused buyers (regulatory-fit mismatch)."),
        Technique(id: "contrast",        name: "Perceptual contrast",         cluster: .framing, mechanism: "A reference point set just before the target shifts how the target is judged — the same price reads as small after a larger anchor, large after a smaller one. Sequential, not absolute, evaluation.", atlasVerdict: .wellStudied, folkloreRisk: .lowMedium, canonicalSource: "Cialdini 1984 (contrast principle); Tversky & Kahneman 1974 (anchoring)", primaryFailureMode: "An implausible reference point reads as a manipulation rather than a comparison, and the contrast inverts into distrust.", contraindication: "Persuasion-knowledge-high buyers who recognize the staged comparison; unverifiable reference points."),
        Technique(id: "gain-framing",    name: "Gain framing",                cluster: .framing, mechanism: "Outcome-positive framing matches promotion-focus regulatory state.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Higgins 1997", primaryFailureMode: "Heterogeneous by buyer's regulatory focus; not universal.", contraindication: "Prevention-focused buyers."),
        Technique(id: "regulatory-fit",  name: "Regulatory fit",              cluster: .framing, mechanism: "Matching buyer's regulatory focus (prevention vs promotion) to message frame increases fluency and persuasion.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Higgins 1997, 1998", primaryFailureMode: "Misdiagnosis of buyer's regulatory focus produces frame inversion.", contraindication: "Requires accurate buyer-read first."),
        Technique(id: "concrete-construal", name: "Concrete-vs-abstract framing", cluster: .framing, mechanism: "Psychologically-near framing matches near-construal of immediate decisions.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Trope & Liberman 2010; Voss 2016", primaryFailureMode: "Abstract framing at decision moment fails.", contraindication: "Early discovery where buyer needs abstract orientation."),

        // D · Structural close
        Technique(id: "assumptive",         name: "Assumptive close",         cluster: .structuralClose, mechanism: "Default-option psychology; reframes decision from 'if' to 'which'.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins 1980; Tracy 1995", primaryFailureMode: "Folklore-risk high. Felt-power inflates confidence in effect.", contraindication: "Most contexts pending Atlas verdict."),
        Technique(id: "alternative-choice", name: "Alternative-choice close", cluster: .structuralClose, mechanism: "Narrows decision space; default option reduces overwhelm.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Tracy", primaryFailureMode: "Folklore-risk high.", contraindication: "When the two options are not both favorable to seller."),
        Technique(id: "summary-close",      name: "Summary close",            cluster: .structuralClose, mechanism: "Explicit summary of agreed value reduces decision uncertainty.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Hopkins; Rackham (SPIN); Dixon (Challenger)", primaryFailureMode: "Generic summary not mirroring buyer language.", contraindication: "When buyer hasn't yet articulated value criteria."),
        Technique(id: "trial-close",        name: "Trial close",              cluster: .structuralClose, mechanism: "Elicits intermediate commitment; surfaces objections early.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Hopkins; SPIN", primaryFailureMode: "Premature trial close before discovery complete.", contraindication: "Before qualification is established."),
        Technique(id: "takeaway",           name: "Takeaway close",           cluster: .structuralClose, mechanism: "Activates reactance and loss aversion; creates pursuit dynamic.", atlasVerdict: .untested, folkloreRisk: .mediumHigh, canonicalSource: "Voss 2016; Belfort", primaryFailureMode: "Read as bluff when BATNA lacks credibility.", contraindication: "Without genuine BATNA. Procurement specialists."),
        Technique(id: "ben-franklin",       name: "Ben Franklin close",       cluster: .structuralClose, mechanism: "Systematic enumeration favors seller's framing (more pros pre-loaded).", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Tracy", primaryFailureMode: "Folklore-risk high. Vibes-heavy.", contraindication: "Sophisticated B2B buyers; reads as theater."),
        Technique(id: "puppy-dog",          name: "Puppy-dog close",          cluster: .structuralClose, mechanism: "Endowment effect after possession.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Hopkins; SaaS industry; endowment literature (Kahneman 1991)", primaryFailureMode: "Free-trial without onboarding produces churn not endowment.", contraindication: "When trial friction is high enough to prevent endowment."),
        Technique(id: "sharp-angle",        name: "Sharp-angle close",        cluster: .structuralClose, mechanism: "Locks objection into commitment via conditional concession.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Belfort", primaryFailureMode: "Folklore-risk high. Ethics-flagged in repeat-game.", contraindication: "Any repeat-game context."),

        // E · Question-form
        Technique(id: "calibrated-question", name: "Calibrated question",     cluster: .questionForm, mechanism: "Open-ended how/what stem invites buyer-generated elaboration; converts no-stance to problem-solving stance.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Voss 2016; Miller & Rollnick 2012; Rackham 1988", primaryFailureMode: "Regression to leading-question phrasing under live pressure.", contraindication: "When direct factual answer was required."),
        Technique(id: "labeling",            name: "Affect labeling",         cluster: .questionForm, mechanism: "Verbalizing emotion reduces amygdala activation; signals empathy.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Voss 2016; Lieberman 2007", primaryFailureMode: "Scripted overuse triggers persuasion-knowledge.", contraindication: "Without genuine affect to label."),
        Technique(id: "mirroring",           name: "Mirroring",               cluster: .questionForm, mechanism: "Last-3-words echo signals attention; minimal-encourager extends counterparty turn.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Voss 2016", primaryFailureMode: "Echo-density triggers persuasion-knowledge.", contraindication: "When counterparty's last words don't invite elaboration."),
        Technique(id: "accusation-audit",    name: "Accusation audit",        cluster: .questionForm, mechanism: "Preemptively naming buyer's likely objections inoculates against them.", atlasVerdict: .untested, folkloreRisk: .medium, canonicalSource: "Voss 2016", primaryFailureMode: "Wrong-axis accusation surfaces objection buyer didn't have.", contraindication: "When the accusation isn't actually being made."),
        Technique(id: "spin-implication",    name: "SPIN implication question", cluster: .questionForm, mechanism: "Elicits buyer-generated cost of the problem; raises perceived problem severity.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Rackham 1988", primaryFailureMode: "Premature implication before problem is established.", contraindication: "Before buyer agrees a problem exists."),
        Technique(id: "spin-need-payoff",    name: "SPIN need-payoff question", cluster: .questionForm, mechanism: "Elicits buyer-generated benefits; pre-commits buyer to solution rationale.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Rackham 1988", primaryFailureMode: "Asked before implication is felt; feels manipulative.", contraindication: "Before buyer feels the problem cost."),

        // F · Negotiation-anchor
        Technique(id: "extreme-anchor",    name: "Extreme anchor",     cluster: .negotiationAnchor, mechanism: "Initial number anchors counterparty's adjustment.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Tversky & Kahneman 1974; Voss 2016; Galinsky", primaryFailureMode: "Anchor without BATNA produces walk-away.", contraindication: "Without credible BATNA."),
        Technique(id: "precise-anchor",    name: "Precise number anchor", cluster: .negotiationAnchor, mechanism: "Precise numbers signal information; counterparty adjusts less.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Mason et al. 2013", primaryFailureMode: "Over-precision when buyer hasn't accepted negotiation frame.", contraindication: "Before pricing discussion is open."),
        Technique(id: "anchor-with-range", name: "Range anchor",       cluster: .negotiationAnchor, mechanism: "Range anchors with backed-bottom outperform point anchors.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Ames & Mason 2015", primaryFailureMode: "Range too wide signals uncertainty.", contraindication: "Adversarial counterparty."),
        Technique(id: "bracketing",        name: "Bracketing",         cluster: .negotiationAnchor, mechanism: "Offers a range that brackets the target; counterparty meets in middle.", atlasVerdict: .untested, folkloreRisk: .medium, canonicalSource: "Voss 2016", primaryFailureMode: "Target visible to counterparty undermines effect.", contraindication: "When target inference is easy."),

        // G · Post-objection
        Technique(id: "feel-felt-found",     name: "Feel-felt-found",         cluster: .postObjection, mechanism: "Validates concern, then social-proof reframes.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Tracy", primaryFailureMode: "Scripted-cliche risk; pattern recognized immediately.", contraindication: "Persuasion-knowledge-high buyers."),
        Technique(id: "isolate-and-conquer", name: "Isolate-the-objection",  cluster: .postObjection, mechanism: "Elicits commitment that this is the only objection; remove it and commitment follows.", atlasVerdict: .untested, folkloreRisk: .medium, canonicalSource: "Sandler; Belfort", primaryFailureMode: "Buyer hides true objection.", contraindication: "When buyer has political reasons to surface false objection."),
        Technique(id: "reverse-objection",   name: "Boomerang / reverse objection", cluster: .postObjection, mechanism: "Reframes objection as a reason to buy.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Tracy", primaryFailureMode: "Brittle. Reads as denial.", contraindication: "Genuine deal-blocking objections."),

        // H · Closing-environment
        Technique(id: "silence",          name: "Strategic silence after offer", cluster: .closingEnvironment, mechanism: "Discomfort-with-silence pushes counterparty to fill it (often with concession or commitment).", atlasVerdict: .untested, folkloreRisk: .medium, canonicalSource: "Sandler; Voss 2016", primaryFailureMode: "Broken too early.", contraindication: "Across cultural contexts where silence is comfortable."),
        Technique(id: "mutual-close-plan", name: "Mutual close plan (MAP)",      cluster: .closingEnvironment, mechanism: "Explicit shared timeline reduces stalls; multi-threading via named stakeholders.", atlasVerdict: .untested, folkloreRisk: .lowMedium, canonicalSource: "MEDDIC; Force Management; commercial data (Gong/SBI)", primaryFailureMode: "MAP without exit-criteria becomes theater.", contraindication: "Single-stakeholder transactional deals."),
        Technique(id: "multi-threading",   name: "Multi-threading",              cluster: .closingEnvironment, mechanism: "Parallel relationships across stakeholders prevents single-point-of-failure on close.", atlasVerdict: .untested, folkloreRisk: .lowMedium, canonicalSource: "Challenger Sale; MEDDIC; commercial data (CEB)", primaryFailureMode: "Multi-threading without champion installation = noise.", contraindication: "Transactional consumer contexts."),
    ]

    private static let byId: [String: Technique] = Dictionary(uniqueKeysWithValues: all.map { ($0.id, $0) })

    public static func get(_ id: String) -> Technique? {
        byId[id]
    }

    public static func name(for id: String) -> String {
        byId[id]?.name ?? id
    }
}
